cssCode:
.blob {
  position: absolute;
  width: 250px; height: 250px;
  border-radius: 50%;
  filter: blur(40px);
  opacity: 0.6;
  animation: floatBlob 8s infinite alternate ease-in-out;
  pointer-events: none;
}
.blob-1 { background: #7928ca; top: -50px; left: -50px; }
.blob-2 { background: #ff0080; bottom: -50px; right: -50px; animation-delay: -4s; }

@keyframes floatBlob {
  0% { transform: translate(0, 0) scale(1); }
  100% { transform: translate(80px, 80px) scale(1.2); }
}

